    msg.topic += ' (kWh)';
}

return msg;

var remaining = msg.payload.message.ratelimit.remaining || 0;
var limit = msg.payload.message.ratelimit.limit;

flow.set('forecast.solar.ratelimit.remaining', remaining)
flow.set('forecast.solar.ratelimit.limit', limit)

return msg;

var remaining = flow.get('forecast.solar.ratelimit.remaining') || -1;
var limit = flow.get('forecast.solar.ratelimit.limit') || -1

var text = remaining.toString() + '/' + limit.toString();
var fill = "green";

if (remaining == 0) {
    fill = "red";
    text = "Limit used";
}

if (remaining > 0 && remaining < limit / 2) {
    fill = "yellow"
}

if (remaining == -1 ) {
    fill = "blue"
    text = "Limits unknown"
}

msg.payload = ({ fill: fill, text: text });

return msg;

node.warn(msg.payload)
msg.payload = ({ fill: "red", text: msg.payload });

return msg;

msg.resolution = 60;
msg.days = 1;
msg.type = env.get('type');
msg.watt = env.get('watt');
msg.kwhoutput = env.get('kwhoutput');

var key1 = Object.keys(msg.payload.result)[1];
var key2 = Object.keys(msg.payload.result)[2];
var key3 = Object.keys(msg.payload.result)[Object.keys(msg.payload.result).length-1];

var d1 = new Date(key1);
var d2 = new Date(key2); 
var d3 = new Date(key3);
msg.resolution = 3600000 / (d2.getTime() - d1.getTime());

msg.days = Math.floor((d3.getTime() - d1.getTime()) / (1000 * 3600 * 24));

if (msg.watt === 'watt_hours_day' || msg.watt === 'watthours/day') {
    msg.resolution = null;
}

return msg;

let new_mode = 0;
if (msg.payload == "Mode 1")
    new_mode = 1;
else if (msg.payload == "Mode 2")
    new_mode = 2;
else
    return null;
msg.payload = new_mode;
return msg;

msg.topic = "charge_state";

if (msg.payload == 0)
    msg.payload = "Initialising";
else if (msg.payload == 1)
    msg.payload = "Bulk";
else if (msg.payload == 2)
    msg.payload = "Absorption";
else if (msg.payload == 3)
    msg.payload = "Float";
else if (msg.payload == 4)
    msg.payload = "Storage";
else if (msg.payload == 5)
    msg.payload = "Absorb repeat";
else if (msg.payload == 6)
    msg.payload = "Forced absorb";
else if (msg.payload == 7)
    msg.payload = "Equalise";
else if (msg.payload == 8)
    msg.payload = "Bulk stopped";
else if (msg.payload == 9)
    msg.payload = "Unknown";
else
    msg.payload = "Unknown?";
msg.sendnow = true;
return msg;

msg.topic = "ess_mode";
