let data = context.global.data || {};
let max_charge_setpoint = context.global.max_charge_setpoint
let min_discharge_setpoint = -context.global.max_discharge_setpoint
let ess_setpoint = msg.payload
node.warn("Setpoint says: "+ess_setpoint)

if (msg.payload > max_charge_setpoint)
    msg.payload = max_charge_setpoint;
else if (msg.payload < min_discharge_setpoint)
    msg.payload = min_discharge_setpoint;

data["original_setpoint"] = ess_setpoint // save setpoint changes unless they are power adjustments
context.global.setpoint_adjusted = false
node.warn("Setting Adjusted to False")
data["ess_setpoint"] = ess_setpoint // save the setpoint we started with so we can re-adjust to it later
context.global.data = data
node.warn("saving original setpoint: "+ ess_setpoint)

return msg;

let data = context.global.data || {};
let soc = msg.payload;
data["batt_soc"] = soc;
msg.payload = (context.global.batt_capacity / 100) * soc;
msg.topic = "batt_capacity";
return msg;

let data_msg = context.global.data || {};
let data_timestamp = context.global.timetamp || {};

let atime = Date.now();

for (var key in data_msg)
{
    let timestamp = 0;
    if (data_timestamp.hasOwnProperty(key)) {
        timestamp = data_timestamp[key];
    }
    if (data_msg.hasOwnProperty(key))
    {
        let timediff = (atime - timestamp) / 1000;
        if (timediff < 60)
            continue;
        //node.warn("key: " + key + ", value: " + data_msg[key] + ", time: "  + timestamp);
        msg.topic = key;
        msg.payload = data_msg[key];
        msg.sendnow = true;
        node.send(msg);
    }
}
return;

let msg2 = RED.util.cloneMessage(msg);
msg2.payload = 0;
if (msg.payload < 0)
{
    msg2.payload = Math.abs(msg.payload);
    msg.payload = 0;
}
return [msg, msg2];

let total = 0;
if (msg.payload.phase_1 != null) {
