}
if (msg.payload.phase_2 != null) {
    total += msg.payload.phase_2;
}
if (msg.payload.phase_3 != null) {
    total += msg.payload.phase_3;
}
msg.topic = "inv_acin_w"
msg.payload = total;
return msg;

let total = 0;
if (msg.payload.et_phase_1 != null) {
    total += msg.payload.et_phase_1;
}
if (msg.payload.et_phase_2 != null) {
    total += msg.payload.et_phase_2;
}
if (msg.payload.et_phase_3 != null) {
