let data = context.global.data;
let sp = data["ess_setpoint"] || 0;
let original_sp = data["original_setpoint"];
let max = context.global.max_charge_setpoint;
let max_phase = context.global.max_phase_power;
let min = -context.global.max_discharge_setpoint;
let idle_rate = context.global.idle_rate;
let adjusted = context.global.setpoint_adjusted || false;
let p1 = data["grid_l1_w"] || 0;
let p2 = data["grid_l2_w"] || 0;
let p3 = data["grid_l3_w"] || 0;
let new_sp = sp;
let num_multi = context.global.number_of_multiplus;
//node.warn("P1, P2, P3 " + p1 + " " + p2 + " " + p3)
//node.warn("sp " + sp)
//node.warn("In Power Monitor, adjusted is "+adjusted)

if (adjusted == false) {
    if (((p1 > max_phase) || (p2 > max_phase) || (p3 > max_phase)) && (sp > idle_rate)) {
        // charge
        node.warn("Charge overload adjust");
	    let highest_phase_power = Math.max(p1,p2,p3);           // phase with the highest load
	    let delta = highest_phase_power - max_phase;            // how much over the max for the phase
	    new_sp = Math.ceil(sp - (delta * num_multi));           // lower for each inverter as one setpoint for all
	    //node.warn("Diff is "+delta+" for a new setpoint of "+new_sp);
	    if (new_sp < 0) {                                        // lets not switch to a discharge state
    	    // prevent a discharge so go to idle
	        new_sp = idle_rate;
	    }
	    node.warn("Setting new setpoint now to "+new_sp);
	    context.global.setpoint_adjusted = true;
	    context.global.data["original_setpoint"] = sp;
    }
    else if (((p1 < -max_phase) || (p2 < -max_phase) ||  (p3 < -max_phase)) && (sp < 0)) { 
        // discharge
        node.warn("Discharge overload adjust");
	    let highest_phase_power = Math.min(p1,p2,p3);           // phase with the highest load
	    let delta = highest_phase_power + max_phase;            // how much over the max for the phase
	    new_sp = Math.floor(sp - (delta * num_multi));          // increase for each inverter as one setpoint for all
	    if (new_sp > 0) {                                        // lets not switch to a charge state
    	    // prevent to adust to charge in a discharge state
	        new_sp = -1;
	    }
	    node.warn("Setting new setpoint now to "+new_sp);
	    context.global.setpoint_adjusted = true;
	    context.global.data["original_setpoint"] = sp;
    }
}
else { // the setpoint was adjusted, check if we can re-adjust 
	if (sp > 0) {                                     // charging in an adjusted state
        node.warn("In Charge re-adjust");
		let highest_phase_power = Math.max(p1, p2, p3);     // find the phase with the highest power
		let delta = max_phase - highest_phase_power;        // see if there is room to adjust
		//node.warn("Delta "+delta);
	 	if (delta > 150) {                                   // only adjust if the diff is > 150W
			new_sp = Math.ceil(Math.min((sp + (delta * num_multi)), original_sp)); // add the delta to the setpoint but do not exceed original_setpoint
			node.warn("Re-adjusting SP from "+sp+" to "+new_sp+ " original was "+original_sp);
			if (new_sp == original_sp) {
				context.global.setpoint_adjusted = false;     // we are back at the original setpoint so set adjusted to false
				//node.warn("adjusted == false " + new_sp + " " + original_sp);
			}
		}
	}
	else if (sp < 0) {                                       // discharging in an adjusted stage
        node.warn("Discharge re-adjust")
		let highest_phase_power = Math.min(p1, p2, p3);     // find the phase with the highest (negative) power
		let delta = -max_phase - highest_phase_power;       // see if there is room to adjust
		//node.warn("Delta "+delta);
	 	if (delta < -150) {                                   // only adjust of diff > 150W
			new_sp = Math.floor(Math.max((sp + (delta * num_multi)), original_sp)); //add the delta to the setpoint but do not exceed original_setpoint
			node.warn("Re-adjusting SP to "+new_sp);
			if (new_sp == original_sp) {
				context.global.setpoint_adjusted = false;     // we are back at the original setpoint so set adjusted to false
				//node.warn("adjusted == false " + new_sp + " " + original_sp);
			}
		}
	}
}
//node.warn("The end, sp: "+sp+" new: "+new_sp);

if (new_sp != sp) {                                          // only adjust of the setpoint has changed
	msg.payload = new_sp;
